window.SITE=window.SITE||{};window.SITE.code={"items":[{"section":"design","file":"src/sicsim/design.py","name":"sobol_pool","label":"후보 풀: Sobol 설계","start":43,"end":49,"html":"<span class=\"k\">def</span> <span class=\"nf\">sobol_pool</span>(n, bounds<span class=\"o\">=</span><span class=\"kc\">None</span>, seed<span class=\"o\">=</span><span class=\"m\">0</span>, prefix<span class=\"o\">=</span><span class=\"s\">\"C\"</span>, names<span class=\"o\">=</span>DESIGN_VARS) <span class=\"o\">-&gt;</span> pd.DataFrame:\n    <span class=\"s\">\"\"\"Scrambled Sobol pool; row order = Sobol order (used by the 'Sobol-fixed' policy).\"\"\"</span>\n    bounds <span class=\"o\">=</span> bounds <span class=\"ow\">or</span> load_bounds()\n    s <span class=\"o\">=</span> qmc.Sobol(d<span class=\"o\">=</span><span class=\"nb\">len</span>(names), scramble<span class=\"o\">=</span><span class=\"kc\">True</span>, seed<span class=\"o\">=</span>seed)\n    m <span class=\"o\">=</span> <span class=\"nb\">int</span>(np.ceil(np.log2(<span class=\"nb\">max</span>(n, <span class=\"m\">2</span>))))\n    u <span class=\"o\">=</span> s.random_base2(m)[:n]\n    <span class=\"k\">return</span> _frame(_scale(u, bounds, names), prefix, names)","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/design.py#L43-L49"},{"section":"design","file":"src/sicsim/devices.py","name":"dmosfet_geometry","label":"JFET 폭 변화(셀 피치 고정)","start":91,"end":116,"html":"<span class=\"k\">def</span> <span class=\"nf\">dmosfet_geometry</span>(cfg, wjfet_scale<span class=\"o\">=</span><span class=\"m\">1.0</span>):\n    <span class=\"s\">\"\"\"Half-cell geometry.  wjfet_mode (geometry key):\n    fixed_pitch   (v1.1 default): the mask pitch is fixed; a JFET-width variation moves the self-aligned\n                  P-well / n+ source edge by -dW/2, so the channel length and the half-cell width (and the\n                  Ron,sp area normalisation) stay constant  -&gt; physical PROCESS variation.\n    pitch_scaling (v1.0): the half-cell grows with the JFET width (design-dimension study).\"\"\"</span>\n    g <span class=\"o\">=</span> <span class=\"nb\">dict</span>(cfg[<span class=\"s\">\"mosfet\"</span>][<span class=\"s\">\"geometry\"</span>])\n    mode <span class=\"o\">=</span> g.get(<span class=\"s\">\"wjfet_mode\"</span>, <span class=\"s\">\"pitch_scaling\"</span>)\n    w0 <span class=\"o\">=</span> g[<span class=\"s\">\"wjfet_um\"</span>]\n    g[<span class=\"s\">\"wjfet_um\"</span>] <span class=\"o\">=</span> w0 <span class=\"o\">*</span> wjfet_scale\n    <span class=\"k\">if</span> mode <span class=\"o\">==</span> <span class=\"s\">\"fixed_pitch\"</span>:\n        shift <span class=\"o\">=</span> <span class=\"m\">0.5</span> <span class=\"o\">*</span> (g[<span class=\"s\">\"wjfet_um\"</span>] <span class=\"o\">-</span> w0)                  <span class=\"c1\"># &gt; 0: wider JFET, narrower P-well</span>\n        g[<span class=\"s\">\"x_half_um\"</span>] <span class=\"o\">=</span> g[<span class=\"s\">\"x_pw_um\"</span>] <span class=\"o\">+</span> <span class=\"m\">0.5</span> <span class=\"o\">*</span> w0             <span class=\"c1\"># fixed half-pitch</span>\n        g[<span class=\"s\">\"x_pw_um\"</span>] <span class=\"o\">-=</span> shift\n        g[<span class=\"s\">\"x_ns1_um\"</span>] <span class=\"o\">-=</span> shift\n        g[<span class=\"s\">\"wjfet_shift_um\"</span>] <span class=\"o\">=</span> shift\n    <span class=\"k\">elif</span> mode <span class=\"o\">==</span> <span class=\"s\">\"pitch_scaling\"</span>:\n        g[<span class=\"s\">\"x_half_um\"</span>] <span class=\"o\">=</span> g[<span class=\"s\">\"x_pw_um\"</span>] <span class=\"o\">+</span> <span class=\"m\">0.5</span> <span class=\"o\">*</span> g[<span class=\"s\">\"wjfet_um\"</span>]\n    <span class=\"k\">else</span>:\n        <span class=\"k\">raise</span> <span class=\"nb\">ValueError</span>(<span class=\"s\">f\"</span><span class=\"s\">unknown wjfet_mode </span>{mode<span class=\"o\">!</span>r}<span class=\"s\">\"</span>)\n    <span class=\"k\">if</span> <span class=\"ow\">not</span> (g[<span class=\"s\">\"x_ox_start_um\"</span>] <span class=\"o\">&lt;</span> g[<span class=\"s\">\"x_ns1_um\"</span>] <span class=\"o\">&lt;</span> g[<span class=\"s\">\"x_pw_um\"</span>] <span class=\"o\">&lt;</span> g[<span class=\"s\">\"x_half_um\"</span>]\n            <span class=\"ow\">and</span> g[<span class=\"s\">\"x_src_contact_um\"</span>] <span class=\"o\">&lt;</span> g[<span class=\"s\">\"x_ns1_um\"</span>]):\n        <span class=\"k\">raise</span> <span class=\"nb\">ValueError</span>(<span class=\"s\">f\"</span><span class=\"s\">invalid half-cell geometry for wjfet_scale=</span>{wjfet_scale}<span class=\"s\">: </span>{g}<span class=\"s\">\"</span>)\n    g[<span class=\"s\">\"y_sub_um\"</span>] <span class=\"o\">=</span> g[<span class=\"s\">\"t_drift_um\"</span>]\n    g[<span class=\"s\">\"y_max_um\"</span>] <span class=\"o\">=</span> g[<span class=\"s\">\"t_drift_um\"</span>] <span class=\"o\">+</span> g[<span class=\"s\">\"t_sub_um\"</span>]\n    <span class=\"k\">return</span> g","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/devices.py#L91-L116"},{"section":"data","file":"src/sicsim/simulate.py","name":"run_mosfet","label":"DEVSIM 바이어스 스윕(전달·출력 특성)","start":38,"end":152,"html":"<span class=\"k\">def</span> <span class=\"nf\">run_mosfet</span>(cfg, T, wjfet_scale<span class=\"o\">=</span><span class=\"m\">1.0</span>, npwell_scale<span class=\"o\">=</span><span class=\"m\">1.0</span>, qit_eff_cm2<span class=\"o\">=</span><span class=\"kc\">None</span>, mu_channel_scale<span class=\"o\">=</span><span class=\"m\">1.0</span>,\n               mesh_scale<span class=\"o\">=</span><span class=\"kc\">None</span>, extended<span class=\"o\">=</span><span class=\"kc\">None</span>, holes<span class=\"o\">=</span><span class=\"kc\">None</span>, output_curve<span class=\"o\">=</span><span class=\"kc\">True</span>) <span class=\"o\">-&gt;</span> <span class=\"nb\">dict</span>:\n    num, b <span class=\"o\">=</span> cfg[<span class=\"s\">\"numerics\"</span>], cfg[<span class=\"s\">\"bias\"</span>]\n    ext <span class=\"o\">=</span> <span class=\"nb\">bool</span>(num.get(<span class=\"s\">\"extended_precision\"</span>, <span class=\"kc\">False</span>)) <span class=\"k\">if</span> extended <span class=\"ow\">is</span> <span class=\"kc\">None</span> <span class=\"k\">else</span> <span class=\"nb\">bool</span>(extended)\n    holes <span class=\"o\">=</span> <span class=\"nb\">bool</span>(num.get(<span class=\"s\">\"holes\"</span>, <span class=\"kc\">False</span>)) <span class=\"k\">if</span> holes <span class=\"ow\">is</span> <span class=\"kc\">None</span> <span class=\"k\">else</span> <span class=\"nb\">bool</span>(holes)\n    ms <span class=\"o\">=</span> <span class=\"nb\">float</span>(cfg[<span class=\"s\">\"mosfet\"</span>].get(<span class=\"s\">\"mesh_scale\"</span>, <span class=\"m\">1.0</span>)) <span class=\"k\">if</span> mesh_scale <span class=\"ow\">is</span> <span class=\"kc\">None</span> <span class=\"k\">else</span> <span class=\"nb\">float</span>(mesh_scale)\n    tol <span class=\"o\">=</span> num[<span class=\"s\">\"tol\"</span>]\n    ii <span class=\"o\">=</span> num.get(<span class=\"s\">\"incomplete_ionization\"</span>, <span class=\"kc\">True</span>)\n    mode <span class=\"o\">=</span> num.get(<span class=\"s\">\"interface_mode\"</span>, <span class=\"s\">\"static\"</span>)\n    intf <span class=\"o\">=</span> <span class=\"nb\">dict</span>(cfg[<span class=\"s\">\"interface\"</span>])\n    <span class=\"k\">if</span> qit_eff_cm2 <span class=\"ow\">is</span> <span class=\"ow\">not</span> <span class=\"kc\">None</span>:\n        intf[<span class=\"s\">\"qit_eff_cm2\"</span>] <span class=\"o\">=</span> <span class=\"nb\">float</span>(qit_eff_cm2)\n    qit_nominal <span class=\"o\">=</span> <span class=\"nb\">float</span>(intf[<span class=\"s\">\"qit_eff_cm2\"</span>])            <span class=\"c1\"># DOE label (defined at 300 K)</span>\n    qT <span class=\"o\">=</span> <span class=\"nb\">float</span>(intf.get(<span class=\"s\">\"qit_T_reduction_423\"</span>, <span class=\"m\">0.0</span>) <span class=\"ow\">or</span> <span class=\"m\">0.0</span>)\n    <span class=\"k\">if</span> qT:   <span class=\"c1\"># robustness variant: |Qit_eff| decreases linearly with T, by the fraction qT at 423 K (none at 300 K)</span>\n        intf[<span class=\"s\">\"qit_eff_cm2\"</span>] <span class=\"o\">=</span> qit_nominal <span class=\"o\">*</span> (<span class=\"m\">1.0</span> <span class=\"o\">-</span> qT <span class=\"o\">*</span> (<span class=\"nb\">float</span>(T) <span class=\"o\">-</span> <span class=\"m\">300.0</span>) <span class=\"o\">/</span> <span class=\"m\">123.0</span>)\n    mat <span class=\"o\">=</span> material_from(cfg)\n    mat.mu_surf300 <span class=\"o\">*=</span> <span class=\"nb\">float</span>(mu_channel_scale)\n    gate <span class=\"o\">=</span> gate_from(cfg)\n\n    solver.STATS <span class=\"o\">=</span> SolveStats()\n    reset_devsim()\n    ph.set_extended_precision(ext)\n    t0 <span class=\"o\">=</span> time.time()\n    rec <span class=\"o\">=</span> <span class=\"nb\">dict</span>(temperature_K<span class=\"o\">=</span><span class=\"nb\">float</span>(T), wjfet_scale<span class=\"o\">=</span><span class=\"nb\">float</span>(wjfet_scale), npwell_scale<span class=\"o\">=</span><span class=\"nb\">float</span>(npwell_scale),\n               qit_eff_cm2<span class=\"o\">=</span>qit_nominal, qit_eff_at_T_cm2<span class=\"o\">=</span><span class=\"nb\">float</span>(intf[<span class=\"s\">\"qit_eff_cm2\"</span>]), mu_channel_scale<span class=\"o\">=</span><span class=\"nb\">float</span>(mu_channel_scale),\n               mesh_scale<span class=\"o\">=</span>ms, extended<span class=\"o\">=</span>ext, holes<span class=\"o\">=</span>holes, converged<span class=\"o\">=</span><span class=\"kc\">False</span>, error_code<span class=\"o\">=</span><span class=\"kc\">None</span>, stage<span class=\"o\">=</span><span class=\"kc\">None</span>)\n    tr <span class=\"o\">=</span> <span class=\"nb\">dict</span>(vgs<span class=\"o\">=</span>[], <span class=\"nb\">id</span><span class=\"o\">=</span>[], is_<span class=\"o\">=</span>[])\n    out <span class=\"o\">=</span> <span class=\"nb\">dict</span>(vgs<span class=\"o\">=</span><span class=\"nb\">float</span>(b[<span class=\"s\">\"vgs_on\"</span>]), vds<span class=\"o\">=</span>[], <span class=\"nb\">id</span><span class=\"o\">=</span>[])\n    <span class=\"k\">try</span>:\n        rec[<span class=\"s\">\"stage\"</span>] <span class=\"o\">=</span> <span class=\"s\">\"build\"</span>\n        <span class=\"k\">with</span> solver.quiet():\n            lay <span class=\"o\">=</span> dv.build_dmosfet(<span class=\"s\">\"m\"</span>, cfg, wjfet_scale, npwell_scale, ms)\n            dv.setup_physics(<span class=\"s\">\"m\"</span>, lay, mat, T, ii<span class=\"o\">=</span>ii, intf_mode<span class=\"o\">=</span>mode, interface<span class=\"o\">=</span>intf, gate<span class=\"o\">=</span>gate)\n        rec.update(n_nodes<span class=\"o\">=</span>lay[<span class=\"s\">\"info\"</span>][<span class=\"s\">\"n_nodes\"</span>], mesh_hash<span class=\"o\">=</span>lay[<span class=\"s\">\"info\"</span>][<span class=\"s\">\"mesh_hash\"</span>],\n                   width_cm<span class=\"o\">=</span>lay[<span class=\"s\">\"info\"</span>][<span class=\"s\">\"area_cm\"</span>])\n        rec[<span class=\"s\">\"stage\"</span>] <span class=\"o\">=</span> <span class=\"s\">\"equilibrium\"</span>\n        dv.equilibrate(<span class=\"s\">\"m\"</span>, lay, ii<span class=\"o\">=</span>ii, intf_mode<span class=\"o\">=</span>mode, tol<span class=\"o\">=</span>tol, holes<span class=\"o\">=</span>holes)\n        rec[<span class=\"s\">\"stage\"</span>] <span class=\"o\">=</span> <span class=\"s\">\"vds_lin\"</span>\n        ramp(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"drain\"</span>, b[<span class=\"s\">\"vds_lin\"</span>], <span class=\"m\">0.05</span>, tol<span class=\"o\">=</span>tol)\n\n        ex <span class=\"o\">=</span> cfg.get(<span class=\"s\">\"extract\"</span>, {})\n        targets <span class=\"o\">=</span> <span class=\"nb\">sorted</span>({<span class=\"o\">*</span>ex.get(<span class=\"s\">\"ss_window_A_per_cm\"</span>, []), ex.get(<span class=\"s\">\"icc_A_per_cm\"</span>, <span class=\"m\">1e-4</span>)})\n        vg_at <span class=\"o\">=</span> {}\n\n        <span class=\"k\">def</span> <span class=\"nf\">refine</span>(t, v0, i0, v1, i1, iters<span class=\"o\">=</span><span class=\"m\">4</span>):\n            <span class=\"s\">\"\"\"Secant on log10(ID) between bracketing transfer points -&gt; VGS where ID = t (removes\n            grid-interpolation error from Vth/SS; extra solves are not added to the curve).\"\"\"</span>\n            lt <span class=\"o\">=</span> math.log10(t)\n            <span class=\"k\">for</span> _ <span class=\"ow\">in</span> <span class=\"nb\">range</span>(iters):\n                <span class=\"k\">if</span> i0 <span class=\"o\">&gt;</span> <span class=\"m\">0</span> <span class=\"ow\">and</span> i1 <span class=\"o\">&gt;</span> <span class=\"m\">0</span>:\n                    f <span class=\"o\">=</span> (lt <span class=\"o\">-</span> math.log10(i0)) <span class=\"o\">/</span> (math.log10(i1) <span class=\"o\">-</span> math.log10(i0))\n                    v <span class=\"o\">=</span> v0 <span class=\"o\">+</span> <span class=\"nb\">min</span>(<span class=\"nb\">max</span>(f, <span class=\"m\">0.02</span>), <span class=\"m\">0.98</span>) <span class=\"o\">*</span> (v1 <span class=\"o\">-</span> v0)\n                <span class=\"k\">else</span>:\n                    v <span class=\"o\">=</span> <span class=\"m\">0.5</span> <span class=\"o\">*</span> (v0 <span class=\"o\">+</span> v1)\n                ds.set_parameter(device<span class=\"o\">=</span><span class=\"s\">\"m\"</span>, name<span class=\"o\">=</span>ph.bias_name(<span class=\"s\">\"gate\"</span>), value<span class=\"o\">=</span>v)\n                <span class=\"k\">try</span>:\n                    solver.solve_dc(<span class=\"s\">\"m\"</span>, tol)\n                <span class=\"k\">except</span> ConvergenceError:\n                    <span class=\"k\">return</span> <span class=\"kc\">None</span>\n                i <span class=\"o\">=</span> ph.contact_current(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"drain\"</span>)\n                <span class=\"k\">if</span> i <span class=\"o\">&gt;</span> <span class=\"m\">0</span> <span class=\"ow\">and</span> <span class=\"nb\">abs</span>(math.log10(i) <span class=\"o\">-</span> lt) <span class=\"o\">&lt;</span> <span class=\"m\">1e-5</span>:\n                    <span class=\"k\">return</span> v\n                <span class=\"k\">if</span> i <span class=\"o\">&lt;</span> t:\n                    v0, i0 <span class=\"o\">=</span> v, i\n                <span class=\"k\">else</span>:\n                    v1, i1 <span class=\"o\">=</span> v, i\n            <span class=\"k\">return</span> v\n\n        <span class=\"k\">def</span> <span class=\"nf\">rec_tr</span>(v):\n            tr[<span class=\"s\">\"vgs\"</span>].append(<span class=\"nb\">float</span>(v))\n            tr[<span class=\"s\">\"id\"</span>].append(ph.contact_current(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"drain\"</span>))\n            tr[<span class=\"s\">\"is_\"</span>].append(ph.contact_current(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"source\"</span>))\n            <span class=\"k\">if</span> <span class=\"nb\">len</span>(tr[<span class=\"s\">\"vgs\"</span>]) <span class=\"o\">&gt;</span> <span class=\"m\">1</span>:\n                v0, i0, i1 <span class=\"o\">=</span> tr[<span class=\"s\">\"vgs\"</span>][<span class=\"o\">-</span><span class=\"m\">2</span>], tr[<span class=\"s\">\"id\"</span>][<span class=\"o\">-</span><span class=\"m\">2</span>], tr[<span class=\"s\">\"id\"</span>][<span class=\"o\">-</span><span class=\"m\">1</span>]\n                <span class=\"k\">for</span> t <span class=\"ow\">in</span> targets:\n                    <span class=\"k\">if</span> <span class=\"s\">f\"</span>{t:<span class=\"s\">.3e</span>}<span class=\"s\">\"</span> <span class=\"ow\">not</span> <span class=\"ow\">in</span> vg_at <span class=\"ow\">and</span> i0 <span class=\"o\">&lt;</span> t <span class=\"o\">&lt;=</span> i1:\n                        vg_at[<span class=\"s\">f\"</span>{t:<span class=\"s\">.3e</span>}<span class=\"s\">\"</span>] <span class=\"o\">=</span> refine(t, v0, i0, <span class=\"nb\">float</span>(v), i1)\n\n        rec_tr(<span class=\"m\">0.0</span>)\n        rec[<span class=\"s\">\"stage\"</span>] <span class=\"o\">=</span> <span class=\"s\">\"transfer\"</span>\n        <span class=\"k\">for</span> stop, step <span class=\"ow\">in</span> b[<span class=\"s\">\"vgs_segments\"</span>]:\n            ramp(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"gate\"</span>, stop, step, tol<span class=\"o\">=</span>tol, callback<span class=\"o\">=</span>rec_tr)\n        <span class=\"k\">if</span> output_curve:\n            rec[<span class=\"s\">\"stage\"</span>] <span class=\"o\">=</span> <span class=\"s\">\"output\"</span>\n            ramp(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"gate\"</span>, b[<span class=\"s\">\"vgs_on\"</span>], <span class=\"m\">0.5</span>, tol<span class=\"o\">=</span>tol)\n\n            <span class=\"k\">def</span> <span class=\"nf\">rec_out</span>(v):\n                out[<span class=\"s\">\"vds\"</span>].append(<span class=\"nb\">float</span>(v))\n                out[<span class=\"s\">\"id\"</span>].append(ph.contact_current(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"drain\"</span>))\n\n            rec_out(b[<span class=\"s\">\"vds_lin\"</span>])\n            <span class=\"k\">try</span>:\n                <span class=\"k\">for</span> stop, step <span class=\"ow\">in</span> b[<span class=\"s\">\"vds_segments\"</span>]:\n                    ramp(<span class=\"s\">\"m\"</span>, <span class=\"s\">\"drain\"</span>, stop, step, tol<span class=\"o\">=</span>tol, callback<span class=\"o\">=</span>rec_out)\n            <span class=\"k\">except</span> ConvergenceError <span class=\"k\">as</span> e:\n                <span class=\"c1\"># protocol rule: output curve may stop early if it reached vds_required (Ron and</span>\n                <span class=\"c1\"># id@vds_required stay defined); otherwise the run fails</span>\n                <span class=\"k\">if</span> <span class=\"ow\">not</span> out[<span class=\"s\">\"vds\"</span>] <span class=\"ow\">or</span> <span class=\"nb\">max</span>(out[<span class=\"s\">\"vds\"</span>]) <span class=\"o\">&lt;</span> b.get(<span class=\"s\">\"vds_required\"</span>, <span class=\"m\">2.0</span>) <span class=\"o\">-</span> <span class=\"m\">1e-9</span>:\n                    <span class=\"k\">raise</span>\n                rec[<span class=\"s\">\"output_truncated_at_V\"</span>] <span class=\"o\">=</span> <span class=\"nb\">max</span>(out[<span class=\"s\">\"vds\"</span>])\n                rec[<span class=\"s\">\"output_note\"</span>] <span class=\"o\">=</span> <span class=\"nb\">str</span>(e)[:<span class=\"m\">200</span>]\n        rec[<span class=\"s\">\"converged\"</span>] <span class=\"o\">=</span> <span class=\"kc\">True</span>\n        rec[<span class=\"s\">\"stage\"</span>] <span class=\"o\">=</span> <span class=\"s\">\"done\"</span>\n        rec[<span class=\"s\">\"vg_at_current\"</span>] <span class=\"o\">=</span> vg_at\n    <span class=\"k\">except</span> ConvergenceError <span class=\"k\">as</span> e:\n        rec[<span class=\"s\">\"error_code\"</span>] <span class=\"o\">=</span> <span class=\"s\">f\"</span><span class=\"s\">CONVERGENCE@</span>{rec[<span class=\"s\">'stage'</span>]}<span class=\"s\">: </span>{e}<span class=\"s\">\"</span>[:<span class=\"m\">300</span>]\n    <span class=\"k\">except</span> <span class=\"nb\">Exception</span> <span class=\"k\">as</span> e:  <span class=\"c1\"># noqa: BLE001 - logged, never silently dropped</span>\n        rec[<span class=\"s\">\"error_code\"</span>] <span class=\"o\">=</span> <span class=\"s\">f\"</span>{<span class=\"nb\">type</span>(e).<span class=\"nb\">__name__</span>}<span class=\"s\">@</span>{rec[<span class=\"s\">'stage'</span>]}<span class=\"s\">: </span>{e}<span class=\"s\">\"</span>[:<span class=\"m\">300</span>]\n    rec[<span class=\"s\">\"runtime_s\"</span>] <span class=\"o\">=</span> <span class=\"nb\">round</span>(time.time() <span class=\"o\">-</span> t0, <span class=\"m\">3</span>)\n    st <span class=\"o\">=</span> solver.STATS.as_dict()\n    rec.update(st, retry_count<span class=\"o\">=</span>st[<span class=\"s\">\"n_fail\"</span>])\n    rec[<span class=\"s\">\"curves\"</span>] <span class=\"o\">=</span> <span class=\"nb\">dict</span>(transfer<span class=\"o\">=</span>tr, output<span class=\"o\">=</span>out)\n    rec.update(protocol_hashes(cfg, ext, holes))\n    <span class=\"k\">return</span> rec","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/simulate.py#L38-L152"},{"section":"data","file":"src/sicsim/extract.py","name":"vth_constant_current","label":"V_th 추출(정전류)","start":30,"end":31,"html":"<span class=\"k\">def</span> <span class=\"nf\">vth_constant_current</span>(vg, idd, icc):\n    <span class=\"k\">return</span> vg_at_current(vg, idd, icc)","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/extract.py#L30-L31"},{"section":"data","file":"src/sicsim/extract.py","name":"extract_features","label":"특징 17개 추출","start":76,"end":107,"html":"<span class=\"k\">def</span> <span class=\"nf\">extract_features</span>(rec: <span class=\"nb\">dict</span>, cfg: <span class=\"nb\">dict</span>) <span class=\"o\">-&gt;</span> <span class=\"nb\">dict</span>:\n    ex <span class=\"o\">=</span> cfg[<span class=\"s\">\"extract\"</span>]\n    tr, out <span class=\"o\">=</span> rec[<span class=\"s\">\"curves\"</span>][<span class=\"s\">\"transfer\"</span>], rec[<span class=\"s\">\"curves\"</span>][<span class=\"s\">\"output\"</span>]\n    vg, idd <span class=\"o\">=</span> tr[<span class=\"s\">\"vgs\"</span>], tr[<span class=\"s\">\"id\"</span>]\n    lo, hi <span class=\"o\">=</span> ex[<span class=\"s\">\"ss_window_A_per_cm\"</span>]\n    floor <span class=\"o\">=</span> kcl_floor(tr[<span class=\"s\">\"id\"</span>], tr[<span class=\"s\">\"is_\"</span>])\n    gm, vgm <span class=\"o\">=</span> gm_max(vg, idd)\n    va <span class=\"o\">=</span> rec.get(<span class=\"s\">\"vg_at_current\"</span>) <span class=\"ow\">or</span> {}\n    key <span class=\"o\">=</span> <span class=\"k\">lambda</span> t: <span class=\"s\">f\"</span>{t:<span class=\"s\">.3e</span>}<span class=\"s\">\"</span>\n    vth_i, ss_i <span class=\"o\">=</span> vth_constant_current(vg, idd, ex[<span class=\"s\">\"icc_A_per_cm\"</span>]), subthreshold_swing(vg, idd, lo, hi)\n    vth <span class=\"o\">=</span> va.get(key(ex[<span class=\"s\">\"icc_A_per_cm\"</span>])) <span class=\"ow\">or</span> vth_i            <span class=\"c1\"># bias-refined value preferred</span>\n    ss <span class=\"o\">=</span> (<span class=\"m\">1e3</span> <span class=\"o\">*</span> (va[key(hi)] <span class=\"o\">-</span> va[key(lo)]) <span class=\"o\">/</span> math.log10(hi <span class=\"o\">/</span> lo)\n          <span class=\"k\">if</span> va.get(key(hi)) <span class=\"ow\">and</span> va.get(key(lo)) <span class=\"k\">else</span> ss_i)\n    f <span class=\"o\">=</span> <span class=\"nb\">dict</span>(\n        vth_V<span class=\"o\">=</span>vth, ss_mV_dec<span class=\"o\">=</span>ss, vth_interp_V<span class=\"o\">=</span>vth_i, ss_interp_mV_dec<span class=\"o\">=</span>ss_i,\n        refined<span class=\"o\">=</span><span class=\"nb\">bool</span>(va),\n        gm_max_S_per_cm<span class=\"o\">=</span>gm, vg_at_gm_max_V<span class=\"o\">=</span>vgm,\n        ion_A_per_cm<span class=\"o\">=</span>current_at(vg, idd, ex[<span class=\"s\">\"vgs_on\"</span>]),\n        ron_mohm_cm2<span class=\"o\">=</span>ron_sp(out[<span class=\"s\">\"vds\"</span>], out[<span class=\"s\">\"id\"</span>], ex[<span class=\"s\">\"ron_vds_max\"</span>], rec.get(<span class=\"s\">\"width_cm\"</span>, <span class=\"nb\">float</span>(<span class=\"s\">\"nan\"</span>))),\n        id_vds_req_A_per_cm<span class=\"o\">=</span>current_at(out[<span class=\"s\">\"vds\"</span>], out[<span class=\"s\">\"id\"</span>], cfg[<span class=\"s\">\"bias\"</span>].get(<span class=\"s\">\"vds_required\"</span>, <span class=\"m\">2.0</span>))\n        <span class=\"k\">if</span> out[<span class=\"s\">\"id\"</span>] <span class=\"k\">else</span> <span class=\"nb\">float</span>(<span class=\"s\">\"nan\"</span>),\n        vds_reached_V<span class=\"o\">=</span><span class=\"nb\">float</span>(<span class=\"nb\">max</span>(out[<span class=\"s\">\"vds\"</span>])) <span class=\"k\">if</span> out[<span class=\"s\">\"vds\"</span>] <span class=\"k\">else</span> <span class=\"nb\">float</span>(<span class=\"s\">\"nan\"</span>),\n        ioff_A_per_cm<span class=\"o\">=</span><span class=\"nb\">abs</span>(<span class=\"nb\">float</span>(idd[<span class=\"m\">0</span>])) <span class=\"k\">if</span> <span class=\"nb\">len</span>(idd) <span class=\"k\">else</span> <span class=\"nb\">float</span>(<span class=\"s\">\"nan\"</span>),\n        kcl_floor_A_per_cm<span class=\"o\">=</span>floor,\n    )\n    f[<span class=\"s\">\"ron_norm\"</span>] <span class=\"o\">=</span> f[<span class=\"s\">\"ron_mohm_cm2\"</span>]                     <span class=\"c1\"># legacy column name (same value)</span>\n    f[<span class=\"s\">\"ioff_below_floor\"</span>] <span class=\"o\">=</span> <span class=\"nb\">bool</span>(f[<span class=\"s\">\"ioff_A_per_cm\"</span>] <span class=\"o\">&lt;</span> <span class=\"m\">10</span> <span class=\"o\">*</span> floor) <span class=\"k\">if</span> np.isfinite(floor) <span class=\"k\">else</span> <span class=\"kc\">None</span>\n    f[<span class=\"s\">\"ss_window_resolved\"</span>] <span class=\"o\">=</span> <span class=\"nb\">bool</span>(np.isfinite(f[<span class=\"s\">\"ss_mV_dec\"</span>]) <span class=\"ow\">and</span> lo <span class=\"o\">&gt;</span> <span class=\"m\">10</span> <span class=\"o\">*</span> floor)\n    <span class=\"k\">for</span> v <span class=\"ow\">in</span> ex[<span class=\"s\">\"feature_vgs\"</span>]:\n        i <span class=\"o\">=</span> current_at(vg, idd, <span class=\"nb\">float</span>(v))\n        f[<span class=\"s\">f\"</span><span class=\"s\">logid_vg</span>{v:<span class=\"s\">g</span>}<span class=\"s\">\"</span>] <span class=\"o\">=</span> math.log10(i) <span class=\"k\">if</span> i <span class=\"o\">&gt;</span> <span class=\"m\">0</span> <span class=\"k\">else</span> <span class=\"nb\">float</span>(<span class=\"s\">\"nan\"</span>)\n    <span class=\"k\">return</span> f","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/extract.py#L76-L107"},{"section":"estimate","file":"src/sicsim/analysis.py","name":"add_noise","label":"측정 잡음","start":58,"end":82,"html":"<span class=\"k\">def</span> <span class=\"nf\">add_noise</span>(wide: pd.DataFrame, noise_cfg: <span class=\"nb\">dict</span>, level: <span class=\"nb\">float</span> <span class=\"o\">=</span> <span class=\"m\">1.0</span>, seed: <span class=\"nb\">int</span> <span class=\"o\">=</span> <span class=\"m\">0</span>) <span class=\"o\">-&gt;</span> pd.DataFrame:\n    <span class=\"s\">\"\"\"Return a copy of a wide table with measurement-like noise on every '&lt;feature&gt;@&lt;T&gt;' column.\n    vth_V: absolute sigma; listed features: relative sigma (log10 columns get log10(1+eps));\n    logid_vg* samples: relative sigma in the log domain.  level=0 -&gt; unchanged copy.\"\"\"</span>\n    out <span class=\"o\">=</span> wide.copy()\n    <span class=\"k\">if</span> level <span class=\"o\">&lt;=</span> <span class=\"m\">0</span>:\n        <span class=\"k\">return</span> out\n    rng <span class=\"o\">=</span> np.random.default_rng(seed)\n    <span class=\"k\">for</span> c <span class=\"ow\">in</span> [c <span class=\"k\">for</span> c <span class=\"ow\">in</span> wide.columns <span class=\"k\">if</span> <span class=\"s\">\"@\"</span> <span class=\"ow\">in</span> <span class=\"nb\">str</span>(c)]:\n        f <span class=\"o\">=</span> c.rsplit(<span class=\"s\">\"@\"</span>, <span class=\"m\">1</span>)[<span class=\"m\">0</span>]\n        n <span class=\"o\">=</span> <span class=\"nb\">len</span>(out)\n        <span class=\"k\">if</span> f <span class=\"ow\">in</span> noise_cfg.get(<span class=\"s\">\"absolute\"</span>, {}):\n            out[c] <span class=\"o\">=</span> out[c] <span class=\"o\">+</span> rng.normal(<span class=\"m\">0</span>, noise_cfg[<span class=\"s\">\"absolute\"</span>][f] <span class=\"o\">*</span> level, n)\n            <span class=\"k\">continue</span>\n        rel <span class=\"o\">=</span> noise_cfg.get(<span class=\"s\">\"relative\"</span>, {}).get(f)\n        <span class=\"k\">if</span> rel <span class=\"ow\">is</span> <span class=\"kc\">None</span> <span class=\"ow\">and</span> f.startswith(<span class=\"s\">\"logid_vg\"</span>):\n            rel <span class=\"o\">=</span> noise_cfg.get(<span class=\"s\">\"logid_samples\"</span>, <span class=\"m\">0.0</span>)\n        <span class=\"k\">if</span> <span class=\"ow\">not</span> rel:\n            <span class=\"k\">continue</span>\n        eps <span class=\"o\">=</span> np.clip(rng.normal(<span class=\"m\">0</span>, rel <span class=\"o\">*</span> level, n), <span class=\"o\">-</span><span class=\"m\">0.5</span>, <span class=\"m\">0.5</span>)\n        <span class=\"k\">if</span> f <span class=\"ow\">in</span> LOGT <span class=\"ow\">or</span> f.startswith(<span class=\"s\">\"logid_vg\"</span>):\n            out[c] <span class=\"o\">=</span> out[c] <span class=\"o\">+</span> np.log10(<span class=\"m\">1</span> <span class=\"o\">+</span> eps)\n        <span class=\"k\">else</span>:\n            out[c] <span class=\"o\">=</span> out[c] <span class=\"o\">*</span> (<span class=\"m\">1</span> <span class=\"o\">+</span> eps)\n    <span class=\"k\">return</span> out","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/analysis.py#L58-L82"},{"section":"estimate","file":"src/sicsim/controls.py","name":"control_feature_set","label":"S1·S1×2·S2 특징 세트","start":102,"end":113,"html":"<span class=\"k\">def</span> <span class=\"nf\">control_feature_set</span>(n1: pd.DataFrame, n2: pd.DataFrame, name: <span class=\"nb\">str</span>, temps<span class=\"o\">=</span>(<span class=\"m\">300</span>, <span class=\"m\">423</span>)) <span class=\"o\">-&gt;</span> pd.DataFrame:\n    <span class=\"s\">\"\"\"S1 / S2 / S3 from the first realisation (frozen definitions) or the repeat controls.\"\"\"</span>\n    <span class=\"k\">if</span> name <span class=\"ow\">in</span> (<span class=\"s\">\"S1\"</span>, <span class=\"s\">\"S2\"</span>, <span class=\"s\">\"S3\"</span>):\n        <span class=\"k\">return</span> feature_set(n1, name, temps)\n    c1 <span class=\"o\">=</span> [c <span class=\"k\">for</span> c <span class=\"ow\">in</span> n1.columns <span class=\"k\">if</span> <span class=\"nb\">str</span>(c).endswith(<span class=\"s\">f\"</span><span class=\"s\">@</span>{temps[<span class=\"m\">0</span>]}<span class=\"s\">\"</span>)]\n    <span class=\"k\">if</span> name <span class=\"o\">==</span> <span class=\"s\">\"S1x2\"</span>:\n        <span class=\"k\">return</span> (n1[c1] <span class=\"o\">+</span> n2[c1]) <span class=\"o\">/</span> <span class=\"m\">2.0</span>\n    <span class=\"k\">if</span> name <span class=\"o\">==</span> <span class=\"s\">\"S1x2cat\"</span>:\n        b <span class=\"o\">=</span> n2[c1].copy()\n        b.columns <span class=\"o\">=</span> [<span class=\"s\">f\"</span>{c}<span class=\"s\">r</span><span class=\"s\">\"</span> <span class=\"k\">for</span> c <span class=\"ow\">in</span> c1]\n        <span class=\"k\">return</span> pd.concat([n1[c1], b], axis<span class=\"o\">=</span><span class=\"m\">1</span>)\n    <span class=\"k\">raise</span> <span class=\"nb\">ValueError</span>(name)","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/controls.py#L102-L113"},{"section":"estimate","file":"src/sicsim/analysis.py","name":"make_model","label":"역추정 모델(GP·RF·Ridge)","start":103,"end":119,"html":"<span class=\"k\">def</span> <span class=\"nf\">make_model</span>(kind<span class=\"o\">=</span><span class=\"s\">\"rf\"</span>, seed<span class=\"o\">=</span><span class=\"m\">0</span>):\n    <span class=\"k\">if</span> kind <span class=\"o\">==</span> <span class=\"s\">\"rf\"</span>:\n        <span class=\"k\">return</span> RandomForestRegressor(n_estimators<span class=\"o\">=</span><span class=\"m\">300</span>, random_state<span class=\"o\">=</span>seed, n_jobs<span class=\"o\">=</span><span class=\"m\">1</span>)\n    <span class=\"k\">if</span> kind <span class=\"o\">==</span> <span class=\"s\">\"et\"</span>:\n        <span class=\"k\">return</span> ExtraTreesRegressor(n_estimators<span class=\"o\">=</span><span class=\"m\">300</span>, random_state<span class=\"o\">=</span>seed, n_jobs<span class=\"o\">=</span><span class=\"m\">1</span>)\n    <span class=\"k\">if</span> kind <span class=\"o\">==</span> <span class=\"s\">\"gp\"</span>:\n        k <span class=\"o\">=</span> ConstantKernel(<span class=\"m\">1.0</span>) <span class=\"o\">*</span> RBF(<span class=\"m\">1.0</span>) <span class=\"o\">+</span> WhiteKernel(<span class=\"m\">1e-3</span>)\n        <span class=\"k\">return</span> make_pipeline(StandardScaler(), GaussianProcessRegressor(k, normalize_y<span class=\"o\">=</span><span class=\"kc\">True</span>, random_state<span class=\"o\">=</span>seed))\n    <span class=\"k\">if</span> kind <span class=\"o\">==</span> <span class=\"s\">\"ridge\"</span>:                                   <span class=\"c1\"># simple linear inverse baseline</span>\n        <span class=\"k\">from</span> sklearn.linear_model <span class=\"k\">import</span> RidgeCV\n        <span class=\"k\">return</span> make_pipeline(StandardScaler(), RidgeCV(alphas<span class=\"o\">=</span>np.logspace(<span class=\"o\">-</span><span class=\"m\">4</span>, <span class=\"m\">3</span>, <span class=\"m\">15</span>)))\n    <span class=\"k\">if</span> kind <span class=\"o\">==</span> <span class=\"s\">\"xgb\"</span>:\n        <span class=\"k\">from</span> sklearn.multioutput <span class=\"k\">import</span> MultiOutputRegressor\n        <span class=\"k\">from</span> xgboost <span class=\"k\">import</span> XGBRegressor\n        <span class=\"k\">return</span> MultiOutputRegressor(XGBRegressor(n_estimators<span class=\"o\">=</span><span class=\"m\">400</span>, max_depth<span class=\"o\">=</span><span class=\"m\">4</span>, learning_rate<span class=\"o\">=</span><span class=\"m\">0.05</span>,\n                                                 subsample<span class=\"o\">=</span><span class=\"m\">0.9</span>, random_state<span class=\"o\">=</span>seed, n_jobs<span class=\"o\">=</span><span class=\"m\">1</span>))\n    <span class=\"k\">raise</span> <span class=\"nb\">ValueError</span>(kind)","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/analysis.py#L103-L119"},{"section":"estimate","file":"src/sicsim/analysis.py","name":"fit_predict","label":"학습과 예측","start":141,"end":146,"html":"<span class=\"k\">def</span> <span class=\"nf\">fit_predict</span>(Xtr, Ytr, Xte, kind<span class=\"o\">=</span><span class=\"s\">\"rf\"</span>, seed<span class=\"o\">=</span><span class=\"m\">0</span>, bounds<span class=\"o\">=</span><span class=\"kc\">None</span>):\n    bounds <span class=\"o\">=</span> bounds <span class=\"ow\">or</span> load_bounds()\n    lo, hi <span class=\"o\">=</span> _lohi(bounds)\n    m <span class=\"o\">=</span> make_model(kind, seed)\n    m.fit(np.asarray(Xtr, <span class=\"nb\">float</span>), (np.asarray(Ytr, <span class=\"nb\">float</span>) <span class=\"o\">-</span> lo) <span class=\"o\">/</span> (hi <span class=\"o\">-</span> lo))\n    <span class=\"k\">return</span> lo <span class=\"o\">+</span> np.asarray(m.predict(np.asarray(Xte, <span class=\"nb\">float</span>))).reshape(<span class=\"nb\">len</span>(Xte), <span class=\"o\">-</span><span class=\"m\">1</span>) <span class=\"o\">*</span> (hi <span class=\"o\">-</span> lo)","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/analysis.py#L141-L146"},{"section":"select","file":"src/sicsim/alsim.py","name":"run_policy","label":"표본 선택 루프","start":63,"end":125,"html":"<span class=\"k\">def</span> <span class=\"nf\">run_policy</span>(pool: pd.DataFrame, test: pd.DataFrame, policy: <span class=\"nb\">str</span>, seed<span class=\"o\">=</span><span class=\"m\">0</span>, n_init<span class=\"o\">=</span><span class=\"m\">40</span>, batch<span class=\"o\">=</span><span class=\"m\">10</span>, rounds<span class=\"o\">=</span><span class=\"m\">6</span>,\n               set_name<span class=\"o\">=</span><span class=\"s\">\"S2\"</span>, model<span class=\"o\">=</span><span class=\"s\">\"rf\"</span>, llm_cfg<span class=\"o\">=</span><span class=\"kc\">None</span>, llm_log<span class=\"o\">=</span><span class=\"kc\">None</span>, top_n<span class=\"o\">=</span><span class=\"m\">20</span>) <span class=\"o\">-&gt;</span> pd.DataFrame:\n    <span class=\"s\">\"\"\"pool/test: wide tables (index candidate_id; process vars + features). pool row order = Sobol order.\"\"\"</span>\n    bounds <span class=\"o\">=</span> load_bounds()\n    rng <span class=\"o\">=</span> np.random.default_rng(seed)\n    ids <span class=\"o\">=</span> <span class=\"nb\">list</span>(pool.index)\n    pcols <span class=\"o\">=</span> _proc_cols(pool)\n    Xpool, Ppool <span class=\"o\">=</span> feature_set(pool, set_name).values, _norm_proc(pool, bounds, pcols)\n    Xte, Yte <span class=\"o\">=</span> feature_set(test, set_name).values, test[VARS].values\n    n_temps <span class=\"o\">=</span> <span class=\"m\">1</span> <span class=\"k\">if</span> set_name <span class=\"o\">==</span> <span class=\"s\">\"S1\"</span> <span class=\"k\">else</span> <span class=\"m\">2</span>\n    pos <span class=\"o\">=</span> {c: i <span class=\"k\">for</span> i, c <span class=\"ow\">in</span> <span class=\"nb\">enumerate</span>(ids)}\n    sel <span class=\"o\">=</span> <span class=\"nb\">list</span>(rng.choice(ids, n_init, replace<span class=\"o\">=</span><span class=\"kc\">False</span>))   <span class=\"c1\"># identical initial set for all policies (same seed)</span>\n    rows <span class=\"o\">=</span> []\n    <span class=\"k\">for</span> r <span class=\"ow\">in</span> <span class=\"nb\">range</span>(rounds <span class=\"o\">+</span> <span class=\"m\">1</span>):\n        idx <span class=\"o\">=</span> [pos[c] <span class=\"k\">for</span> c <span class=\"ow\">in</span> sel]\n        P <span class=\"o\">=</span> fit_predict(Xpool[idx], pool[VARS].values[idx], Xte, model, seed)\n        m <span class=\"o\">=</span> metrics(Yte, P, bounds)\n        rows.append(<span class=\"nb\">dict</span>(policy<span class=\"o\">=</span>policy, seed<span class=\"o\">=</span>seed, <span class=\"nb\">round</span><span class=\"o\">=</span>r, n_points<span class=\"o\">=</span><span class=\"nb\">len</span>(sel), n_devsim_runs<span class=\"o\">=</span><span class=\"nb\">len</span>(sel) <span class=\"o\">*</span> n_temps,\n                         mean_mae_norm<span class=\"o\">=</span>m[<span class=\"s\">\"mean_mae_norm\"</span>],\n                         <span class=\"o\">**</span>{<span class=\"s\">f\"</span><span class=\"s\">mae_norm_</span>{v}<span class=\"s\">\"</span>: m[v][<span class=\"s\">\"mae_norm\"</span>] <span class=\"k\">for</span> v <span class=\"ow\">in</span> VARS},\n                         <span class=\"o\">**</span>{<span class=\"s\">f\"</span><span class=\"s\">f1_</span>{v}<span class=\"s\">\"</span>: m[v][<span class=\"s\">\"macro_f1\"</span>] <span class=\"k\">for</span> v <span class=\"ow\">in</span> VARS}))\n        <span class=\"k\">if</span> r <span class=\"o\">==</span> rounds:\n            <span class=\"k\">break</span>\n        rest <span class=\"o\">=</span> [c <span class=\"k\">for</span> c <span class=\"ow\">in</span> ids <span class=\"k\">if</span> c <span class=\"ow\">not</span> <span class=\"ow\">in</span> <span class=\"nb\">set</span>(sel)]\n        <span class=\"k\">if</span> policy <span class=\"o\">==</span> <span class=\"s\">\"random\"</span>:\n            new <span class=\"o\">=</span> <span class=\"nb\">list</span>(rng.choice(rest, batch, replace<span class=\"o\">=</span><span class=\"kc\">False</span>))\n        <span class=\"k\">elif</span> policy <span class=\"o\">==</span> <span class=\"s\">\"sobol\"</span>:\n            new <span class=\"o\">=</span> rest[:batch]\n        <span class=\"k\">else</span>:\n            ridx <span class=\"o\">=</span> [pos[c] <span class=\"k\">for</span> c <span class=\"ow\">in</span> rest]\n            unc <span class=\"o\">=</span> forward_uncertainty(Ppool[idx], Xpool[idx], Ppool[ridx], seed)\n            <span class=\"k\">if</span> policy <span class=\"o\">==</span> <span class=\"s\">\"uncertainty\"</span>:\n                new <span class=\"o\">=</span> diverse_top(rest, unc, Ppool[ridx], Ppool[idx], batch)\n            <span class=\"k\">elif</span> policy <span class=\"o\">==</span> <span class=\"s\">\"top20_random\"</span>:\n                top <span class=\"o\">=</span> np.argsort(<span class=\"o\">-</span>unc)[:top_n]\n                new <span class=\"o\">=</span> [rest[j] <span class=\"k\">for</span> j <span class=\"ow\">in</span> top_random(top, batch, np.random.default_rng([seed, r, <span class=\"m\">2020</span>]))]\n            <span class=\"k\">elif</span> policy <span class=\"o\">==</span> <span class=\"s\">\"llm\"</span>:\n                top <span class=\"o\">=</span> np.argsort(<span class=\"o\">-</span>unc)[:top_n]\n                dist <span class=\"o\">=</span> _min_dist(Ppool[ridx][top], Ppool[idx])\n                <span class=\"c1\"># model summary from TRAINING data only (no test-set leakage into the selector)</span>\n                Ptr_cv <span class=\"o\">=</span> np.zeros((<span class=\"nb\">len</span>(idx), <span class=\"nb\">len</span>(VARS)))\n                g <span class=\"o\">=</span> np.array(sel)\n                <span class=\"k\">for</span> a, b <span class=\"ow\">in</span> GroupKFold(n_splits<span class=\"o\">=</span><span class=\"nb\">min</span>(<span class=\"m\">5</span>, <span class=\"nb\">len</span>(idx))).split(Xpool[idx], groups<span class=\"o\">=</span>g):\n                    Ptr_cv[b] <span class=\"o\">=</span> fit_predict(Xpool[idx][a], pool[VARS].values[idx][a], Xpool[idx][b], model, seed)\n                cvm <span class=\"o\">=</span> metrics(pool[VARS].values[idx], Ptr_cv, bounds)\n                payload <span class=\"o\">=</span> <span class=\"nb\">dict</span>(<span class=\"nb\">round</span><span class=\"o\">=</span>r, seed<span class=\"o\">=</span>seed, batch_size<span class=\"o\">=</span>batch,\n                               model_summary<span class=\"o\">=</span><span class=\"nb\">dict</span>(n_train<span class=\"o\">=</span><span class=\"nb\">len</span>(idx), cv_mae_norm<span class=\"o\">=</span>{v: <span class=\"nb\">round</span>(cvm[v][<span class=\"s\">\"mae_norm\"</span>], <span class=\"m\">4</span>) <span class=\"k\">for</span> v <span class=\"ow\">in</span> VARS},\n                                                  worst_target<span class=\"o\">=</span><span class=\"nb\">max</span>(VARS, key<span class=\"o\">=</span><span class=\"k\">lambda</span> v: cvm[v][<span class=\"s\">\"mae_norm\"</span>])),\n                               candidates<span class=\"o\">=</span>[<span class=\"nb\">dict</span>(candidate_id<span class=\"o\">=</span>rest[j],\n                                                <span class=\"o\">**</span>{v: <span class=\"nb\">round</span>(<span class=\"nb\">float</span>(Ppool[ridx][j][q]), <span class=\"m\">3</span>) <span class=\"k\">for</span> q, v <span class=\"ow\">in</span> <span class=\"nb\">enumerate</span>(pcols)},\n                                                predictive_uncertainty<span class=\"o\">=</span><span class=\"nb\">round</span>(<span class=\"nb\">float</span>(unc[j]), <span class=\"m\">4</span>),\n                                                distance_to_train<span class=\"o\">=</span><span class=\"nb\">round</span>(<span class=\"nb\">float</span>(dist[i]), <span class=\"m\">4</span>))\n                                           <span class=\"k\">for</span> i, j <span class=\"ow\">in</span> <span class=\"nb\">enumerate</span>(top)])\n                cfg <span class=\"o\">=</span> llm_cfg <span class=\"ow\">or</span> {<span class=\"s\">\"dry_run\"</span>: <span class=\"kc\">True</span>}\n                variant <span class=\"o\">=</span> cfg.get(<span class=\"s\">\"variant\"</span>, <span class=\"s\">\"named\"</span>)\n                shown, truth <span class=\"o\">=</span> transform_payload(payload, variant, shuffle_rng(seed, r) <span class=\"k\">if</span> variant <span class=\"o\">==</span> <span class=\"s\">\"shuffled\"</span> <span class=\"k\">else</span> <span class=\"kc\">None</span>)\n                new, _ <span class=\"o\">=</span> llm_mod.select(shown, sel, cfg, llm_log, truth<span class=\"o\">=</span>truth)\n                <span class=\"k\">if</span> new <span class=\"ow\">is</span> <span class=\"kc\">None</span>:                  <span class=\"c1\"># fixed fallback rule</span>\n                    new <span class=\"o\">=</span> diverse_top(rest, unc, Ppool[ridx], Ppool[idx], batch)\n            <span class=\"k\">else</span>:\n                <span class=\"k\">raise</span> <span class=\"nb\">ValueError</span>(policy)\n        sel <span class=\"o\">+=</span> <span class=\"nb\">list</span>(new)\n    <span class=\"k\">return</span> pd.DataFrame(rows)","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/alsim.py#L63-L125"},{"section":"select","file":"src/sicsim/alsim.py","name":"diverse_top","label":"불확실도 정책","start":49,"end":60,"html":"<span class=\"k\">def</span> <span class=\"nf\">diverse_top</span>(ids, score, Pc, Ptr, k, top_factor<span class=\"o\">=</span><span class=\"m\">3</span>):\n    <span class=\"s\">\"\"\"Greedy: from the top (top_factor*k) by score, repeatedly take the candidate maximising\n    score * distance to (train + already chosen).\"\"\"</span>\n    order <span class=\"o\">=</span> np.argsort(<span class=\"o\">-</span>score)[: <span class=\"nb\">max</span>(k <span class=\"o\">*</span> top_factor, k)]\n    chosen, ref <span class=\"o\">=</span> [], Ptr.copy()\n    <span class=\"k\">for</span> _ <span class=\"ow\">in</span> <span class=\"nb\">range</span>(k):\n        d <span class=\"o\">=</span> _min_dist(Pc[order], ref)\n        j <span class=\"o\">=</span> order[<span class=\"nb\">int</span>(np.argmax(score[order] <span class=\"o\">*</span> (d <span class=\"o\">+</span> <span class=\"m\">1e-9</span>)))]\n        chosen.append(ids[j])\n        ref <span class=\"o\">=</span> np.vstack([ref, Pc[j]])\n        order <span class=\"o\">=</span> order[order <span class=\"o\">!=</span> j]\n    <span class=\"k\">return</span> chosen","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/alsim.py#L49-L60"},{"section":"select","file":"src/sicsim/schema.py","name":"validate_selection","label":"LLM 응답 검증","start":74,"end":99,"html":"<span class=\"k\">def</span> <span class=\"nf\">validate_selection</span>(raw, allowed_ids, batch_size: <span class=\"nb\">int</span>, already_evaluated<span class=\"o\">=</span>()):\n    <span class=\"s\">\"\"\"Return (LLMSelection, None) if accepted, else (None, reject_reason). Any violation rejects\n    the WHOLE response (no partial acceptance).\"\"\"</span>\n    <span class=\"k\">try</span>:\n        data <span class=\"o\">=</span> json.loads(raw) <span class=\"k\">if</span> <span class=\"nb\">isinstance</span>(raw, (<span class=\"nb\">str</span>, <span class=\"nb\">bytes</span>)) <span class=\"k\">else</span> raw\n    <span class=\"k\">except</span> json.JSONDecodeError <span class=\"k\">as</span> e:\n        <span class=\"k\">return</span> <span class=\"kc\">None</span>, <span class=\"s\">f\"</span><span class=\"s\">INVALID_JSON: </span>{e.msg}<span class=\"s\">\"</span>\n    <span class=\"k\">try</span>:\n        sel <span class=\"o\">=</span> LLMSelection.model_validate(data)\n    <span class=\"k\">except</span> ValidationError <span class=\"k\">as</span> e:\n        err <span class=\"o\">=</span> e.errors()[<span class=\"m\">0</span>]\n        <span class=\"k\">return</span> <span class=\"kc\">None</span>, <span class=\"s\">f\"</span><span class=\"s\">SCHEMA: </span>{<span class=\"s\">'.'</span>.join(<span class=\"nb\">map</span>(<span class=\"nb\">str</span>, err[<span class=\"s\">'loc'</span>]))}<span class=\"s\">: </span>{err[<span class=\"s\">'msg'</span>]}<span class=\"s\">\"</span>\n    ids <span class=\"o\">=</span> sel.selected_ids\n    <span class=\"k\">if</span> <span class=\"nb\">len</span>(ids) <span class=\"o\">!=</span> batch_size:\n        <span class=\"k\">return</span> <span class=\"kc\">None</span>, <span class=\"s\">f\"</span><span class=\"s\">BATCH_SIZE: got </span>{<span class=\"nb\">len</span>(ids)}<span class=\"s\">, expected </span>{batch_size}<span class=\"s\">\"</span>\n    <span class=\"k\">if</span> <span class=\"nb\">len</span>(<span class=\"nb\">set</span>(ids)) <span class=\"o\">!=</span> <span class=\"nb\">len</span>(ids):\n        <span class=\"k\">return</span> <span class=\"kc\">None</span>, <span class=\"s\">\"DUPLICATE_IDS\"</span>\n    allowed <span class=\"o\">=</span> <span class=\"nb\">set</span>(allowed_ids)\n    bad <span class=\"o\">=</span> [i <span class=\"k\">for</span> i <span class=\"ow\">in</span> ids <span class=\"k\">if</span> i <span class=\"ow\">not</span> <span class=\"ow\">in</span> allowed]\n    <span class=\"k\">if</span> bad:\n        <span class=\"k\">return</span> <span class=\"kc\">None</span>, <span class=\"s\">f\"</span><span class=\"s\">OUT_OF_LIST: </span>{bad[:<span class=\"m\">5</span>]}<span class=\"s\">\"</span>\n    done <span class=\"o\">=</span> <span class=\"nb\">set</span>(already_evaluated)\n    rerun <span class=\"o\">=</span> [i <span class=\"k\">for</span> i <span class=\"ow\">in</span> ids <span class=\"k\">if</span> i <span class=\"ow\">in</span> done]\n    <span class=\"k\">if</span> rerun:\n        <span class=\"k\">return</span> <span class=\"kc\">None</span>, <span class=\"s\">f\"</span><span class=\"s\">ALREADY_EVALUATED: </span>{rerun[:<span class=\"m\">5</span>]}<span class=\"s\">\"</span>\n    <span class=\"k\">return</span> sel, <span class=\"kc\">None</span>","url":"https://github.com/mseokq23/sic-mosfet-devsim/blob/90312740daf2e54a21c9c93046d35e9b2e579e13/src/sicsim/schema.py#L74-L99"}]};
